1	import { db } from "@/lib/db";
2	import type { BlogPost } from "@prisma/client";
3	
4	export const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
5	
6	/* ----------------------------------------------------------------------------
7	 * Fetch helpers
8	 * ------------------------------------------------------------------------- */
9	
10	/** Published posts, newest first -- for the public blog index. */
11	export function getPublishedPosts(): Promise<BlogPost[]> {
12	  return db.blogPost.findMany({
13	    where: { published: true },
14	    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
15	  });
16	}
17	
18	/** A single published post by slug, or null (drives notFound() on the page). */
19	export function getPublishedPost(slug: string): Promise<BlogPost | null> {
20	  return db.blogPost.findFirst({ where: { slug, published: true } });
21	}
22	
23	/**
24	 * Full-text-ish search over published posts. Case-insensitive `contains` across
25	 * title / excerpt / body, plus an exact tag match. Empty query falls back to the
26	 * normal newest-first listing. Runs server-side so results are crawlable.
27	 */
28	export function searchPublishedPosts(q: string): Promise<BlogPost[]> {
29	  const query = q.trim();
30	  if (!query) return getPublishedPosts();
31	  return db.blogPost.findMany({
32	    where: {
33	      published: true,
34	      OR: [
35	        { title: { contains: query, mode: "insensitive" } },
36	        { excerpt: { contains: query, mode: "insensitive" } },
37	        { body: { contains: query, mode: "insensitive" } },
38	        { category: { contains: query, mode: "insensitive" } },
39	        { tags: { has: query.toLowerCase() } },
40	      ],
41	    },
42	    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
43	  });
44	}
45	
46	/** Default page size for the paginated blog index. */
47	export const POSTS_PER_PAGE = 12;
48	
49	/** Prisma `where` for the public index -- optionally narrowed by a search query. */
50	function publishedWhere(q?: string) {
51	  const query = (q ?? "").trim();
52	  if (!query) return { published: true } as const;
53	  return {
54	    published: true,
55	    OR: [
56	      { title: { contains: query, mode: "insensitive" as const } },
57	      { excerpt: { contains: query, mode: "insensitive" as const } },
58	      { body: { contains: query, mode: "insensitive" as const } },
59	      { category: { contains: query, mode: "insensitive" as const } },
60	      { tags: { has: query.toLowerCase() } },
61	    ],
62	  };
63	}
64	
65	export type PostsPage = {
66	  posts: BlogPost[];
67	  total: number;
68	  page: number;
69	  totalPages: number;
70	  perPage: number;
71	};
72	
73	/**
74	 * One page of published posts (newest first), optionally filtered by a search
75	 * query. `page` is 1-based and clamped into range. Returns the slice plus enough
76	 * metadata to render prev/next controls and per-page canonicals. Runs a single
77	 * count + a single findMany so the index stays light even with ~200 posts.
78	 */
79	export async function getPostsPage(opts: { page?: number; q?: string; perPage?: number } = {}): Promise<PostsPage> {
80	  const perPage = Math.max(1, opts.perPage ?? POSTS_PER_PAGE);
81	  const where = publishedWhere(opts.q);
82	  const total = await db.blogPost.count({ where });
83	  const totalPages = Math.max(1, Math.ceil(total / perPage));
84	  const page = Math.min(Math.max(1, Math.floor(opts.page ?? 1)), totalPages);
85	  const posts = await db.blogPost.findMany({
86	    where,
87	    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
88	    skip: (page - 1) * perPage,
89	    take: perPage,
90	  });
91	  return { posts, total, page, totalPages, perPage };
92	}
93	
94	/**
95	 * Up to `limit` other published posts related to `post` -- same category first,
96	 * back-filled with the newest posts so the block is never short. The current
97	 * post is always excluded. Drives the "Related articles" internal-linking block
98	 * on the post page (the biggest lever for getting thin/orphaned posts indexed).
99	 */
100	export async function getRelatedPosts(post: BlogPost, limit = 3): Promise<BlogPost[]> {
101	  const sameCategory = await db.blogPost.findMany({
102	    where: { published: true, category: post.category, id: { not: post.id } },
103	    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
104	    take: limit,
105	  });
106	  if (sameCategory.length >= limit) return sameCategory;
107	
108	  // Back-fill with the newest posts, skipping anything already picked.
109	  const have = new Set([post.id, ...sameCategory.map((p) => p.id)]);
110	  const recent = await db.blogPost.findMany({
111	    where: { published: true, id: { notIn: [...have] } },
112	    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
113	    take: limit - sameCategory.length,
114	  });
115	  return [...sameCategory, ...recent];
116	}
117	
118	/**
119	 * Map a post to the single most relevant product page so every article funnels
120	 * to a money page (internal-linking + conversion). Matches the post's category,
121	 * tags and title against product keywords; falls back to the pricing page.
122	 */
123	export function productLinkForPost(post: BlogPost): { label: string; href: string; blurb: string } {
124	  const hay = `${post.category} ${post.tags.join(" ")} ${post.title}`.toLowerCase();
125	  const has = (...ks: string[]) => ks.some((k) => hay.includes(k));
126	
127	  if (has("minecraft", "rust", "game", "valheim", "palworld", "ark", "fivem", "server hosting"))
128	    return {
129	      label: "Game server hosting",
130	      href: "/game-servers",
131	      blurb: "Spin up a ready-to-play game server in minutes -- one-click installs, DDoS protection and instant scaling.",
132	    };
133	  if (has("web hosting", "wordpress", "website", "php", "shared hosting"))
134	    return {
135	      label: "Web hosting",
136	      href: "/web-hosting",
137	      blurb: "Get your site online without managing a server -- PHP, databases, email and free SSL, from a few dollars a month.",
138	    };
139	  if (has("domain", "dns", "nameserver"))
140	    return {
141	      label: "Register a domain",
142	      href: "/domains",
143	      blurb: "Search and register your domain, with free DNS management and one-click connection to your Nxeon services.",
144	    };
145	  if (has("email", "mailbox", "smtp"))
146	    return {
147	      label: "Business email",
148	      href: "/business-email",
149	      blurb: "Professional mailboxes on your own domain, with webmail, IMAP and spam filtering included.",
150	    };
151	  // Default: VPS is the flagship product for everything else (Linux, security,
152	  // Docker, self-hosting).
153	  return {
154	    label: "Cloud VPS hosting",
155	    href: "/vps",
156	    blurb: "Full root access on NVMe cloud VPS with instant deployment -- the flexible way to host anything.",
157	  };
158	}
159	
160	/** Every post regardless of status, newest edit first -- for the admin editor. */
161	export function getAllPosts(): Promise<BlogPost[]> {
162	  return db.blogPost.findMany({ orderBy: { updatedAt: "desc" } });
163	}
164	
165	/** Look up any post by id (admin edit form). */
166	export function getPostById(id: string): Promise<BlogPost | null> {
167	  return db.blogPost.findUnique({ where: { id } });
168	}
169	
170	/* ----------------------------------------------------------------------------
171	 * Formatting
172	 * ------------------------------------------------------------------------- */
173	
174	export function formatDate(d: Date | string | null | undefined): string {
175	  if (!d) return "";
176	  const date = typeof d === "string" ? new Date(d) : d;
177	  return date.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
178	}
179	
180	/** Rough read-time estimate from the raw markdown body. */
181	export function readMinutes(body: string): number {
182	  const words = body.trim().split(/\s+/).filter(Boolean).length;
183	  return Math.max(1, Math.round(words / 200));
184	}
185	
186	/* ----------------------------------------------------------------------------
187	 * Tiny, self-contained markdown -> HTML renderer.
188	 *
189	 * No external dependency. Handles: # / ## / ### headings, **bold**, `code`,
190	 * fenced ``` code blocks, - / * and 1. lists, [links](url), and blank-line
191	 * separated paragraphs. HTML is escaped BEFORE any markdown is applied, and
192	 * inline code spans are protected so their contents are never re-processed.
193	 * Output carries Tailwind classes so it reads well on the dark theme (there is
194	 * no typography plugin installed).
195	 * ------------------------------------------------------------------------- */
196	
197	function esc(s: string): string {
198	  return s
199	    .replace(/&/g, "&amp;")
200	    .replace(/</g, "&lt;")
201	    .replace(/>/g, "&gt;");
202	}
203	
204	const CLS = {
205	  h1: "mt-10 mb-4 text-3xl font-bold tracking-tight text-white",
206	  h2: "mt-10 mb-3 text-2xl font-bold tracking-tight text-white",
207	  h3: "mt-8 mb-2 text-xl font-semibold text-white",
208	  p: "mb-4 leading-relaxed text-slate-300",
209	  ul: "mb-5 list-disc space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
210	  ol: "mb-5 list-decimal space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
211	  li: "leading-relaxed",
212	  a: "text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200",
213	  code: "rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[0.85em] text-brand-200",
214	  pre: "mb-5 overflow-x-auto rounded-xl border border-white/10 bg-navy-950/80 p-4 font-mono text-[13px] leading-relaxed text-slate-200",
215	  img: "w-full rounded-xl border border-white/10 shadow-lg shadow-black/20",
216	};
217	
218	/** Allow only http(s) or root-relative image sources; reject everything else. */
219	function safeSrc(u: string): string {
220	  return /^(https?:\/\/|\/)/.test(u) ? u : "";
221	}
222	
223	// Private-use sentinels wrap protected inline-code indices so they can never
224	// collide with ordinary digits in prose (e.g. "2 GB", "port 25565").
225	const S0 = "\uE000";
226	const S1 = "\uE001";
227	
228	/** Inline markdown for a single run of text. */
229	function inline(text: string): string {
230	  const codes: string[] = [];
231	  // Protect inline code first.
232	  let s = esc(text).replace(/`([^`]+)`/g, (_m, c: string) => {
233	    codes.push(c);
234	    return `${S0}${codes.length - 1}${S1}`;
235	  });
236	  // Bold.
237	  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong class="font-semibold text-white">$1</strong>');
238	  // Underline (__text__) and highlight (==text==) -- additive syntax, no
239	  // existing caller uses either pattern today so there's nothing to collide
240	  // with. Highlight renders as a real <mark>, not just a color, so it still
241	  // reads correctly with a screen reader or in a copy-pasted plain-text quote.
242	  s = s.replace(/__([^_]+)__/g, '<u class="underline decoration-2 underline-offset-2">$1</u>');
243	  s = s.replace(/==([^=]+)==/g, '<mark class="rounded bg-brand-500/25 px-1 text-white">$1</mark>');
244	  // Inline images ![alt](url) -- MUST run before links (they share `[..](..)`).
245	  s = s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, (_m, alt: string, u: string) => {
246	    const safe = safeSrc(u);
247	    if (!safe) return "";
248	    return `<img class="${CLS.img} my-6" src="${safe}" alt="${alt}" loading="lazy" />`;
249	  });
250	  // Links [text](url) -- only http(s), root-relative, or anchors are allowed.
251	  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
252	    const safe = /^(https?:\/\/|\/|#)/.test(u) ? u : "#";
253	    const ext = safe.startsWith("http");
254	    return `<a class="${CLS.a}" href="${safe}"${ext ? ' target="_blank" rel="noopener noreferrer"' : ""}>${t}</a>`;
255	  });
256	  // Restore inline code.
257	  s = s.replace(new RegExp(`${S0}(\\d+)${S1}`, "g"), (_m, i: string) => `<code class="${CLS.code}">${codes[+i]}</code>`);
258	  return s;
259	}
260	
261	/* ----------------------------------------------------------------------------
262	 * Article-aware renderer for the editorial blog template.
263	 *
264	 * Same block/inline grammar as renderMarkdown, but additionally:
265	 *   - gives every heading a stable, unique `id` so the sticky table-of-contents
266	 *     spine + scroll-spy can anchor to it,
267	 *   - returns the H2/H3 outline as a TOC, and
268	 *   - extracts any question-style heading (text ending in "?") + its following
269	 *     prose as an FAQ pair, for FAQ JSON-LD.
270	 *
271	 * Kept separate from renderMarkdown so the four other callers (admin docs,
272	 * announcements, what's-new) are completely untouched.
273	 * ------------------------------------------------------------------------- */
274	
275	export type TocEntry = { id: string; label: string; level: 2 | 3 };
276	export type FaqEntry = { q: string; a: string };
277	export type RenderedArticle = { html: string; toc: TocEntry[]; faq: FaqEntry[] };
278	
279	/** URL-safe, human-readable heading anchor. */
280	export function slugifyHeading(text: string): string {
281	  return (
282	    text
283	      .toLowerCase()
284	      .replace(/`[^`]*`/g, "")
285	      .replace(/[*_[\]()#]/g, "")
286	      .replace(/&[a-z]+;/g, "")
287	      .replace(/[^a-z0-9\s-]/g, "")
288	      .trim()
289	      .replace(/\s+/g, "-")
290	      .slice(0, 60)
291	      .replace(/^-+|-+$/g, "") || "section"
292	  );
293	}
294	
295	/** Strip inline markdown down to plain text (for FAQ answers / meta). */
296	function plainInline(text: string): string {
297	  return text
298	    .replace(/`([^`]+)`/g, "$1")
299	    .replace(/\*\*([^*]+)\*\*/g, "$1")
300	    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
301	    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
302	    .trim();
303	}
304	
305	/** First non-empty prose paragraph of a markdown body, as plain text. */
306	export function firstParagraph(md: string): string {
307	  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
308	  const buf: string[] = [];
309	  for (const line of lines) {
310	    const t = line.trim();
311	    if (!t) {
312	      if (buf.length) break;
313	      continue;
314	    }
315	    if (/^(#{1,3}\s|[-*]\s|\d+\.\s|```|---+$|!\[)/.test(t)) {
316	      if (buf.length) break;
317	      continue;
318	    }
319	    buf.push(t);
320	  }
321	  return plainInline(buf.join(" "));
322	}
323	
324	export function renderMarkdown(md: string): string {
325	  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
326	  const out: string[] = [];
327	  let i = 0;
328	
329	  while (i < lines.length) {
330	    const line = lines[i];
331	
332	    // Blank line -- skip.
333	    if (!line.trim()) { i++; continue; }
334	
335	    // Horizontal rule.
336	    if (/^---+$/.test(line.trim())) {
337	      out.push('<hr class="my-8 border-white/[0.08]" />');
338	      i++;
339	      continue;
340	    }
341	
342	    // A RUN of 2+ consecutive standalone image lines (no blank line or other
343	    // content between them) becomes a horizontally scrollable, snap-to-item
344	    // carousel instead of one figure per line stacked vertically -- useful for
345	    // "here are 6 screenshots" or "here are the game covers we just added"
346	    // without needing any client-side JS: CSS scroll-snap does the paging.
347	    // A single standalone image (the common case -- one screenshot) still
348	    // falls through to the plain captioned-figure path below unchanged.
349	    {
350	      const imgLineRe = /^!\[([^\]]*)\]\(([^)]+)\)$/;
351	      if (imgLineRe.test(line.trim())) {
352	        const run: { alt: string; src: string }[] = [];
353	        let j = i;
354	        while (j < lines.length) {
355	          const m = lines[j].trim().match(imgLineRe);
356	          if (!m) break;
357	          const safe = safeSrc(m[2]);
358	          if (safe) run.push({ alt: esc(m[1]), src: safe });
359	          j++;
360	        }
361	        if (run.length >= 2) {
362	          out.push(
363	            `<div class="my-7 -mx-1 flex snap-x snap-mandatory gap-3 overflow-x-auto px-1 pb-2" ` +
364	              `style="scrollbar-width:thin">` +
365	              run
366	                .map(
367	                  (r) =>
368	                    `<figure class="flex-none snap-center" style="width:min(200px,55%)">` +
369	                      // Fixed height + object-fit:cover, not just a width cap -- a
370	                      // carousel mixes landscape screenshots (~16:9) and portrait
371	                      // game-cover art (~2:3); capping only width let a tall
372	                      // poster's natural aspect ratio blow the image out to
373	                      // near-full viewport height (found live 2026-09-14).
374	                      `<img class="${CLS.img}" style="height:260px;width:100%;object-fit:cover" src="${r.src}" alt="${r.alt}" loading="lazy" />` +
375	                      (r.alt ? `<figcaption class="mt-2 text-center text-xs text-slate-500">${r.alt}</figcaption>` : "") +
376	                      `</figure>`,
377	                )
378	                .join("") +
379	              `</div>`,
380	          );
381	          i = j;
382	          continue;
383	        }
384	      }
385	    }
386	
387	    // Standalone image line -> captioned figure (not wrapped in a paragraph).
388	    const img = line.trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
389	    if (img) {
390	      const safe = safeSrc(img[2]);
391	      if (safe) {
392	        const alt = esc(img[1]);
393	        out.push(
394	          `<figure class="my-7"><img class="${CLS.img}" src="${safe}" alt="${alt}" loading="lazy" />` +
395	            (alt ? `<figcaption class="mt-2 text-center text-xs text-slate-500">${alt}</figcaption>` : "") +
396	            `</figure>`,
397	        );
398	        i++;
399	        continue;
400	      }
401	    }
402	
403	    // Fenced code block.
404	    if (/^```/.test(line.trim())) {
405	      const buf: string[] = [];
406	      i++;
407	      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
408	      i++; // closing fence
409	      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
410	      continue;
411	    }
412	
413	    // Headings.
414	    if (/^###\s+/.test(line)) { out.push(`<h3 class="${CLS.h3}">${inline(line.replace(/^###\s+/, ""))}</h3>`); i++; continue; }
415	    if (/^##\s+/.test(line))  { out.push(`<h2 class="${CLS.h2}">${inline(line.replace(/^##\s+/, ""))}</h2>`);  i++; continue; }
416	    if (/^#\s+/.test(line))   { out.push(`<h1 class="${CLS.h1}">${inline(line.replace(/^#\s+/, ""))}</h1>`);   i++; continue; }
417	
418	    // Ordered list.
419	    if (/^\s*\d+\.\s+/.test(line)) {
420	      const items: string[] = [];
421	      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
422	        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
423	        i++;
424	      }
425	      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ol>`);
426	      continue;
427	    }
428	
429	    // Unordered list.
430	    if (/^\s*[-*]\s+/.test(line)) {
431	      const items: string[] = [];
432	      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
433	        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
434	        i++;
435	      }
436	      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ul>`);
437	      continue;
438	    }
439	
440	    // Paragraph -- gather until a blank line or block boundary.
441	    const para = [line];
442	    i++;
443	    while (
444	      i < lines.length &&
445	      lines[i].trim() &&
446	      !/^#{1,3}\s/.test(lines[i]) &&
447	      !/^\s*[-*]\s+/.test(lines[i]) &&
448	      !/^\s*\d+\.\s+/.test(lines[i]) &&
449	      !/^```/.test(lines[i].trim()) &&
450	      !/^---+$/.test(lines[i].trim())
451	    ) {
452	      para.push(lines[i]);
453	      i++;
454	    }
455	    out.push(`<p class="${CLS.p}">${inline(para.join(" "))}</p>`);
456	  }
457	
458	  return out.join("\n");
459	}
