461	export function renderArticle(md: string): RenderedArticle {
462	  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
463	  const out: string[] = [];
464	  const toc: TocEntry[] = [];
465	  const faq: FaqEntry[] = [];
466	  const usedIds = new Set<string>();
467	  // A question-style heading whose following prose is still being collected.
468	  let pendingQ: { q: string; ans: string[] } | null = null;
469	  let i = 0;
470	
471	  const uniqueId = (base: string): string => {
472	    let id = base;
473	    let n = 2;
474	    while (usedIds.has(id)) id = `${base}-${n++}`;
475	    usedIds.add(id);
476	    return id;
477	  };
478	  const flushFaq = () => {
479	    if (pendingQ) {
480	      const a = pendingQ.ans.join(" ").replace(/\s+/g, " ").trim();
481	      if (a && faq.length < 12) faq.push({ q: pendingQ.q, a });
482	      pendingQ = null;
483	    }
484	  };
485	  const collect = (text: string) => {
486	    if (pendingQ) pendingQ.ans.push(text);
487	  };
488	
489	  while (i < lines.length) {
490	    const line = lines[i];
491	
492	    if (!line.trim()) { i++; continue; }
493	
494	    if (/^---+$/.test(line.trim())) {
495	      out.push('<hr class="my-8 border-white/[0.08]" />');
496	      i++;
497	      continue;
498	    }
499	
500	    // Standalone image -> captioned figure.
501	    const img = line.trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
502	    if (img) {
503	      const safe = safeSrc(img[2]);
504	      if (safe) {
505	        const alt = esc(img[1]);
506	        out.push(
507	          `<figure class="my-7"><img class="${CLS.img}" src="${safe}" alt="${alt}" loading="lazy" />` +
508	            (alt ? `<figcaption class="mt-2 text-center text-xs text-slate-500">${alt}</figcaption>` : "") +
509	            `</figure>`,
510	        );
511	        i++;
512	        continue;
513	      }
514	    }
515	
516	    // Fenced code block.
517	    if (/^```/.test(line.trim())) {
518	      const buf: string[] = [];
519	      i++;
520	      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
521	      i++;
522	      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
523	      continue;
524	    }
525	
526	    // Headings -- anchor id + outline/FAQ capture.
527	    const hMatch = line.match(/^(#{1,3})\s+(.*)$/);
528	    if (hMatch) {
529	      flushFaq();
530	      const level = hMatch[1].length as 1 | 2 | 3;
531	      const raw = hMatch[2];
532	      const text = plainInline(raw);
533	      const id = uniqueId(slugifyHeading(text));
534	      const cls = level === 1 ? CLS.h1 : level === 2 ? CLS.h2 : CLS.h3;
535	      out.push(`<h${level} id="${id}" class="${cls} scroll-mt-28">${inline(raw)}</h${level}>`);
536	      if (level === 2 || level === 3) toc.push({ id, label: text, level });
537	      if (text.endsWith("?")) pendingQ = { q: text, ans: [] };
538	      i++;
539	      continue;
540	    }
541	
542	    // Ordered list.
543	    if (/^\s*\d+\.\s+/.test(line)) {
544	      const items: string[] = [];
545	      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
546	        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
547	        i++;
548	      }
549	      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ol>`);
550	      collect(items.map(plainInline).join(". "));
551	      continue;
552	    }
553	
554	    // Unordered list.
555	    if (/^\s*[-*]\s+/.test(line)) {
556	      const items: string[] = [];
557	      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
558	        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
559	        i++;
560	      }
561	      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ul>`);
562	      collect(items.map(plainInline).join(". "));
563	      continue;
564	    }
565	
566	    // Paragraph.
567	    const para = [line];
568	    i++;
569	    while (
570	      i < lines.length &&
571	      lines[i].trim() &&
572	      !/^#{1,3}\s/.test(lines[i]) &&
573	      !/^\s*[-*]\s+/.test(lines[i]) &&
574	      !/^\s*\d+\.\s+/.test(lines[i]) &&
575	      !/^```/.test(lines[i].trim()) &&
576	      !/^---+$/.test(lines[i].trim())
577	    ) {
578	      para.push(lines[i]);
579	      i++;
580	    }
581	    out.push(`<p class="${CLS.p}">${inline(para.join(" "))}</p>`);
582	    collect(plainInline(para.join(" ")));
583	  }
584	
585	  flushFaq();
586	  return { html: out.join("\n"), toc, faq };
587	}
