625	  if (has("security", "firewall", "ssh", "ssl", "vpn", "hardening", "fail2ban", "port")) return "shield";
626	  if (has("backup", "snapshot", "restore")) return "backup";
627	  if (has("docker", "linux", "terminal", "command", "cli", "systemd", "bash")) return "terminal";
628	  if (has("performance", "monitor", "ram", "cpu", "benchmark", "speed", "tune")) return "gauge";
629	  if (has("web hosting", "wordpress", "website", "php", "nginx")) return "apps";
630	  if (has("price", "pricing", "cost", "cheap", "compare", "vs", "plan")) return "scale";
631	  return "server";
632	}
