42	/**
43	 * Real revalidate window for the two whole-catalogue aggregates below
44	 * (`listCatalogFamilies`, `totalDownloadsFor`) — both are cheap in isolation
45	 * today (~25-30ms, confirmed live 2026-09-21) but recomputed from scratch on
46	 * EVERY /mods, /mods/games/[family], /dashboard/nxlabs, and
47	 * /dashboard/nxlabs/games/[family] request (these pages are `force-dynamic`,
48	 * so nothing about the route itself is cached). Neither number needs
49	 * second-by-second freshness — a mod's `featured`/`downloads` values only
50	 * change via periodic backfill scripts (scripts/verify-gamemods.ts and
51	 * friends), never a live user action — so wrapping them in Next's real data
52	 * cache with a 10-minute window cuts real, repeated DB round trips under
53	 * concurrent traffic without ever showing stale-by-more-than-10-minutes data.
54	 */
55	const CATALOG_AGGREGATE_REVALIDATE_SECONDS = 600;
