136	/** Real average+count per mod, one groupBy query for as many mods as needed at once. */
137	async function ratingAggs(modIds: string[]): Promise<Map<string, RatingAgg>> {
138	  if (modIds.length === 0) return new Map();
139	  const rows = await db.modRating.groupBy({
140	    by: ["gameModId"],
141	    where: { gameModId: { in: modIds } },
142	    _avg: { rating: true },
143	    _count: { rating: true },
144	  });
145	  return new Map(rows.map((r) => [r.gameModId, { avg: r._avg.rating, count: r._count.rating }]));
146	}
