214	export type CatalogSort = "featured" | "downloads" | "latest" | "rating";
215	
216	export type CatalogPage = {
217	  mods: ModSummary[];
218	  total: number;
219	  page: number;
220	  totalPages: number;
221	  perPage: number;
222	};
223	
224	/**
225	 * Every scalar `orderBy` StoreBrowser's sort tabs can ask for. "rating" is
226	 * the one honest exception: avgRating is computed from a separate ModRating
227	 * table with no cached column on GameMod, and Prisma's relation-aggregate
228	 * `orderBy` only supports `_count` (not `_avg`) for to-many relations — there
229	 * is no cheap DB-side "top rated" ordering to give it. Fetching by downloads
230	 * and re-sorting by rating WITHIN each page (below) is a documented
231	 * approximation: "Top Rated" page 2 shows the 25th-48th most-downloaded mods
232	 * re-ordered by rating, not the true 25th-48th highest-rated mods
233	 * catalogue-wide. That is honest and fine at today's rating volumes (a small
234	 * fraction of 32k+ mods have any reviews at all); if ratings ever justify
235	 * it, add a cached avgRating/ratingCount column on GameMod (maintained by
236	 * the rating mutation) and give this its own real orderBy.
237	 */
238	const ORDER_BY: Record<CatalogSort, Prisma.GameModOrderByWithRelationInput[]> = {
239	  featured: [{ featured: "desc" }, { downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
240	  downloads: [{ downloads: "desc" }, { name: "asc" }],
241	  latest: [{ createdAt: "desc" }],
242	  rating: [{ downloads: "desc" }, { name: "asc" }],
243	};
244	
245	/**
246	 * Real, server-side, paginated + searched + sorted catalogue query — the
247	 * single data source behind every StoreBrowser instance (marketing and
248	 * portal, cross-game and per-family). Replaces the old
249	 * `listCatalogMods`/`searchCatalogMods` pair, which fetched (at most)
250	 * `CATALOG_LIST_CAP` rows once and left every control on top of it running
251	 * over that fixed in-memory array — fine at ~124 hand-seeded rows, silently
252	 * capping the catalogue at families with thousands+ of real imported rows.
253	 */
254	export async function queryCatalogMods(opts: {
255	  family?: string;
256	  /** Category filter — the per-family page's chips (StoreBrowser's `chipField: "category"`). */
257	  category?: string;
258	  q?: string;
259	  sort?: CatalogSort;
260	  page?: number;
261	  perPage?: number;
262	}): Promise<CatalogPage> {
263	  const sort = opts.sort ?? "featured";
264	  const q = (opts.q ?? "").trim();
265	  const where: Prisma.GameModWhereInput = {
266	    active: true,
267	    upstreamOk: true,
268	    ...(opts.family ? { gameFamily: opts.family } : {}),
269	    ...(opts.category ? { category: opts.category } : {}),
270	    ...(q
271	      ? {
272	          OR: [
273	            { name: { contains: q, mode: "insensitive" } },
274	            { category: { contains: q, mode: "insensitive" } },
275	            { description: { contains: q, mode: "insensitive" } },
276	          ],
277	        }
278	      : {}),
279	  };
280	
281	  const total = await db.gameMod.count({ where });
282	  const { skip, take, page, pages, perPage } = paginate(
283	    { page: opts.page != null ? String(opts.page) : undefined },
284	    total,
285	    opts.perPage ?? CATALOG_PAGE_SIZE
286	  );
287	
288	  const rows = await db.gameMod.findMany({ where, orderBy: ORDER_BY[sort], skip, take });
289	  const aggs = await ratingAggs(rows.map((r) => r.id));
290	  const mods = rows.map((r) => toSummary(r, aggs.get(r.id)));
291	  if (sort === "rating") {
292	    mods.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
293	  }
294	
295	  return { mods, total, page, totalPages: pages, perPage };
296	}
297	
298	/**
299	 * Curated "Featured mods" rail — real `GameMod.featured` rows only (an
300	 * admin/import-time editorial flag, same field `ORDER_BY.featured` already
301	 * sorts by first), never a synthetic pick. Ordered by real downloads within
302	 * the featured set so the best-known featured mod leads. Returns fewer than
303	 * `take` (down to zero) when a family simply hasn't had any mods marked
304	 * featured yet — callers render nothing rather than pad with non-featured
305	 * rows, matching this file's no-guessing rule. Omit `family` for a
306	 * cross-game rail (the NxLabs homepage's curated "Featured" row, item 6 of
307	 * the 2026-09-20 overhaul), same optional-family convention as
308	 * listTopDownloadedMods/listRecentlyUpdatedMods below.
309	 */
310	export async function listFeaturedMods(family?: string, take = 8): Promise<ModSummary[]> {
311	  const rows = await db.gameMod.findMany({
312	    where: { active: true, upstreamOk: true, featured: true, ...(family ? { gameFamily: family } : {}) },
313	    orderBy: [{ downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
314	    take,
315	  });
316	  const aggs = await ratingAggs(rows.map((r) => r.id));
317	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
318	}
