440	/**
441	 * One mod's detail. Returns null for an unknown/inactive slug — callers
442	 * should notFound().
443	 *
444	 * DECODES the slug/family before lookup (2026-09-24 fix — see
445	 * docs/DOCUMENTATION.md's dated entry): a page.tsx dynamic route segment
446	 * that also exports `generateStaticParams` gets its `params` value as the
447	 * STILL-PERCENT-ENCODED path segment in this Next.js version (confirmed
448	 * live: requesting `/mods/minecraft/abyss+` — or the equivalently-encoded
449	 * `/mods/minecraft/abyss%2B` — makes `params.slug` arrive as the literal
450	 * string `"abyss%2B"`, not `"abyss+"`; a plain Route Handler on the exact
451	 * same path shape decodes correctly, so this is specific to the
452	 * generateStaticParams + page.tsx combination). Real catalogue slugs
453	 * legitimately contain `+`, `,`, `` ` ``, `"` (Modrinth project slugs are
454	 * not sanitized at import) — 377 of them 404'd because of this. Tries the
455	 * decoded value first (the common, now-fixed case), then falls back to the
456	 * raw value passed in (covers the rare slug that is itself the literal
457	 * string containing a `%`, and keeps this function correct for callers that
458	 * already pass a clean, non-encoded value — decoding twice is a no-op for
459	 * any string with no percent-escapes in it).
460	 */
461	export async function getCatalogMod(family: string, slug: string): Promise<ModDetail | null> {
462	  const decodedFamily = safeDecode(family);
463	  const decodedSlug = safeDecode(slug);
464	  let row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: decodedFamily, slug: decodedSlug } } });
465	  if (!row && (decodedFamily !== family || decodedSlug !== slug)) {
466	    row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: family, slug } } });
467	  }
468	  if (!row || !row.active) return null;
469	  const aggs = await ratingAggs([row.id]);
470	  return toDetail(row, aggs.get(row.id));
471	}
