529	/**
530	 * `id` is the real, live `GamePlan.id` this recommendation resolved to — kept
531	 * on the result (not just derived data) so a caller can hand it straight to
532	 * `deployHref({ gamePlanId })` and land the wizard on this EXACT plan, the
533	 * same real-tier resolution `order.tsx`'s `orderFromIntent` already does for
534	 * a `tier` query param. Never a synthetic id — always one of the
535	 * `gamePlans` rows passed in below.
536	 */
537	export type RecommendedPlan = { id: string; planName: string; ramMB: number; priceCents: number } | null;
538	
539	/**
540	 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
541	 * light-impact mods run on any active plan for the family; moderate needs at
542	 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
543	 * for the family that clears the bar, or null if none does (never guesses a
544	 * number that isn't a real, active, orderable plan). `null` is also the
545	 * honest signal for a family with zero active GamePlan rows at all (e.g.
546	 * "schedule1", which has no official dedicated server and stays unseeded —
547	 * see lib/games.ts) — callers must not render a deploy action in that case.
548	 */
549	export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "id" | "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
550	  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
551	  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
552	  const pick = candidates[0];
553	  return pick ? { id: pick.id, planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
554	}
