570	/**
571	 * An honest, field-derived description for the small slice of active mods
572	 * with neither a real `description` tagline nor a `longDescription` body —
573	 * confirmed live 2026-09-20 (NxLabs overhaul, item 4): 148 of 45,766 active
574	 * mods (0.3%; mostly minimal Steam Workshop skin/map submissions and a
575	 * couple of GitHub repos with a blank `description` field) have nothing at
576	 * all from their source. This is composed only from real columns already on
577	 * the row — category, game, loader/variant, a game version, file size —
578	 * never invented marketing copy. `mod.description` and `mod.longDescription`
579	 * both being empty is the ONLY case that should ever reach this; callers
580	 * must prefer the real fields first.
581	 *
582	 * Separately: the much larger gap — 94.9% of active mods (all 32,243
583	 * Modrinth rows) have a real `description` tagline but no `longDescription`
584	 * — is NOT what this function is for. That gap exists because
585	 * scripts/backfill-modrinth-descriptions.ts, which fetches Modrinth's real
586	 * project `body` and is fully idempotent/rate-limited, has only ever been
587	 * run as a dry run against production, never with `--apply`. That is a
588	 * one-time data-backfill run to do, not a rendering fallback — see this
589	 * task's final report.
590	 */
591	export function composedDescriptionFor(
592	  mod: Pick<ModDetail, "category" | "gameFamilyLabel" | "loaders" | "appliesToVariant" | "gameVersions" | "fileBytes">
593	): string {
594	  const bits = [`A ${mod.category} for ${mod.gameFamilyLabel}`];
595	  const platform = mod.loaders[0] ?? mod.appliesToVariant;
596	  if (platform) bits.push(platform);
597	  const version = mod.gameVersions[mod.gameVersions.length - 1];
598	  if (version) bits.push(`version ${version}`);
599	  let text = `${bits.join(", ")}.`;
600	  const size = formatBytes(mod.fileBytes);
601	  if (size) text += ` ${size} download.`;
602	  return text;
603	}
