605	export function formatBytes(bytes: number | null): string | null {
606	  if (!bytes || bytes <= 0) return null;
607	  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
608	  if (bytes >= 1024 * 1024) return `${Math.round(bytes / (1024 * 1024))} MB`;
609	  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
610	}
