612	export type ResolvedDownload = { url: string; direct: boolean } | null;
613	
614	/**
615	 * The synchronous half of download resolution — every source EXCEPT
616	 * modrinth/thunderstore resolves with no network call at all (spigotmc's
617	 * Spiget endpoint is a constructed URL, everything else is just `mod.url`).
618	 * Returns `undefined` for modrinth/thunderstore specifically, meaning "a
619	 * live external API call is required" — callers that can't afford to block
620	 * on that (see StoreBrowser.tsx) use this to render immediately for the
621	 * ~50% of the catalogue that needs no network at all, and defer the rest to
622	 * an on-demand client resolve.
623	 *
624	 * REAL PERFORMANCE FIX (2026-09-21): `resolveDownloadUrl` below used to be
625	 * called via `Promise.all` for EVERY mod card in StoreBrowser's grid (up to
626	 * `CATALOG_PAGE_SIZE`=24 per /mods and /dashboard/nxlabs page load). That was
627	 * a real, harmless-looking pattern when the catalogue was ~124 hand-seeded
628	 * rows with few resolvable `sourceId`s; the moment the Modrinth bulk import
629	 * landed 32,000+ real rows, most default/browse pages became Modrinth-
630	 * dominated, and every single page load started firing up to 24 concurrent,
631	 * uncached, un-timed-out HTTPS calls to api.modrinth.com as part of server
632	 * rendering — measured live against production at 1-2.2s of REAL added
633	 * latency per page load (see docs/DOCUMENTATION.md's 2026-09-21 entry for
634	 * the exact numbers), with no upper bound if Modrinth itself is ever slow.
635	 * Splitting the sync-resolvable 50%+ of sources out, and deferring the
636	 * network-bound rest to a click-triggered resolve (DownloadButton.tsx +
637	 * lib/actions-mods.ts's resolveModDownloadAction), removes ALL of that from
638	 * the server-render critical path — a card the visitor never clicks now
639	 * costs zero external requests, instead of one whether it's clicked or not.
640	 */
641	export function resolveDownloadUrlSync(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): ResolvedDownload | undefined {
642	  const fallback: ResolvedDownload = mod.url ? { url: mod.url, direct: false } : null;
643	  const id = mod.sourceId ?? "";
644	  if (!id) return fallback;
645	  if (mod.source === "modrinth" || mod.source === "thunderstore") return undefined;
646	  if (mod.source === "spigotmc") {
647	    // Spiget's own download endpoint 302s to the real jar — genuinely direct, no fetch needed to know that.
648	    return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
649	  }
650	  return fallback;
651	}
652	
653	/**
654	 * The uncached live-fetch half of `resolveDownloadUrl` below — pulled out on
655	 * its own so `unstable_cache` (see `resolveDownloadUrlCached`) wraps ONLY the
656	 * tiny resolved `{url, direct}` result, never the raw upstream response body.
657	 *
658	 * REAL BUG FIX (2026-09-22): this used to rely on `next: { revalidate: 3600 }`
659	 * on the `fetch` calls themselves — Next's fetch data-cache, which silently
660	 * refuses to store any response over roughly 2MB and simply re-fetches live
661	 * on every call instead, with no error or warning. Confirmed live via
662	 * journalctl: `minecraft-comes-alive-reborn`'s Modrinth `/version` response is
663	 * 20,035,322 bytes, so it was being re-fetched from api.modrinth.com on
664	 * EVERY single visit to that mod's detail page with zero caching benefit —
665	 * and Modrinth's version-list responses routinely run large for mods with
666	 * many released files, so this wasn't an isolated case. The actual value we
667	 * need to cache is a couple hundred bytes (`{url, direct}`); caching that
668	 * directly via `unstable_cache` sidesteps the fetch-cache size ceiling
669	 * entirely, for every mod regardless of how large its upstream response is.
670	 */
671	async function fetchLiveDownload(source: string, sourceId: string): Promise<{ url: string; direct: boolean } | null> {
672	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
673	  try {
674	    if (source === "modrinth") {
675	      const headers: Record<string, string> = { "User-Agent": UA };
676	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
677	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(sourceId)}/version`, {
678	        headers,
679	        signal: AbortSignal.timeout(5000),
680	      });
681	      if (!res.ok) return null;
682	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
683	      const v = versions[0];
684	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
685	      return file ? { url: file.url, direct: true } : null;
686	    }
687	    if (source === "thunderstore") {
688	      const [namespace, ...rest] = sourceId.split("-");
689	      if (!namespace || !rest.length) return null;
690	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
691	        headers: { "User-Agent": UA },
692	        signal: AbortSignal.timeout(5000),
693	      });
694	      if (!res.ok) return null;
695	      const pkg = (await res.json()) as { latest?: { download_url?: string } };
696	      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : null;
697	    }
698	  } catch {
699	    return null;
700	  }
701	  return null;
702	}
703	
704	const fetchLiveDownloadCached = unstable_cache(fetchLiveDownload, ["mods-catalog:resolveDownloadUrl"], {
705	  revalidate: 3600,
706	});
707	
708	/**
709	 * The real, authoritative download for a mod detail page. Prefers the
710	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
711	 * install it) so a visitor gets the actual file, not just a landing page;
712	 * falls back to the mod's own project/resource page (still the real,
713	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
714	 * be resolved live or isn't one of the three we know how to resolve.
715	 *
716	 * Fine to call eagerly for ONE mod (the detail pages do exactly that) — the
717	 * cost that mattered was calling it for a whole page of cards at once, see
718	 * `resolveDownloadUrlSync` above. Every live fetch carries a 5s timeout
719	 * (`AbortSignal.timeout`) so a slow/unresponsive upstream can never hang this
720	 * past a bounded worst case — there was no timeout at all before 2026-09-21,
721	 * so a degraded Modrinth/Thunderstore response could block a caller
722	 * indefinitely. The live fetch itself is cached via `unstable_cache`, not
723	 * `next: { revalidate }` — see `fetchLiveDownload`'s comment for why.
724	 */
725	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<ResolvedDownload> {
726	  const sync = resolveDownloadUrlSync(mod);
727	  if (sync !== undefined) return sync;
728	
729	  const fallback: ResolvedDownload = mod.url ? { url: mod.url, direct: false } : null;
730	  const id = mod.sourceId ?? "";
731	  const live = await fetchLiveDownloadCached(mod.source, id);
732	  return live ?? fallback;
733	}
