type Search = { q?: string; page?: string };

function parsePage(v?: string): number {
  const n = Number.parseInt(v ?? "1", 10);
  return Number.isFinite(n) && n > 0 ? n : 1;
}

/** Build a /blog URL preserving the search query and page number. */
function pageHref(page: number, q: string): string {
  const params = new URLSearchParams();
  if (q) params.set("q", q);
  if (page > 1) params.set("page", String(page));
  const qs = params.toString();
  return qs ? `/blog?${qs}` : "/blog";
}

export async function generateMetadata({ searchParams }: { searchParams: Promise<Search> }): Promise<Metadata> {
  const { q, page: pageRaw } = await searchParams;
  const query = (q ?? "").trim();
  const page = parsePage(pageRaw);
  const suffix = page > 1 ? ` — page ${page}` : "";
  const title = `Blog — VPS & self-hosting guides${suffix}`;
